typedef unsigned int MENU_UINT32;
typedef unsigned short MENU_UINT16;
typedef char MenuLine[64];

struct MenuColor;
struct MenuRect
{
    MENU_UINT16 x0,y0,x1,y1;
};
class Menu;

extern int MENU_BorderSizeFactor( void );
extern int MENU_BorderSpaceFactor( void );
extern int MENU_TextHeight( const char *text );
extern int MENU_TextSeparation( void );

class MenuRender
{
    MenuRect limit;
    MenuRect inuse;
    MenuLine text[16];
    MENU_UINT32 state[16];
    int active;
    int topentry;

public:
    virtual ~MenuRender();
    virtual void OpenMenu( Menu *m );
    virtual void CloseMenu( void );
    void Refresh( void );

protected:
    virtual int TotalEntries( void )=0;
    virtual MENU_UINT32 GetElementState( int i )=0;
    virtual void GetElementText( int i, char *t, int len )=0;
    virtual MenuColor GetElementColor( int i )=0;
};

void MenuRender::Refresh( void )
{
    int aent=0;
    for ( int j=0; j<TotalEntries(); j++ )
    {
        if ( GetElementState(j) & 4 )
        {
            aent=j;
            break;
        }
    }
    if ( aent < topentry )
    {
        topentry=aent;
    }

    bool checked=false;
    while ( !checked )
    {
        checked=true;
        int acount=0;
        int y=inuse.y0+2*MENU_BorderSpaceFactor()+2*MENU_BorderSizeFactor();
        for ( int k=topentry; k<TotalEntries(); k++ )
        {
            char ttext[64];
            GetElementText(k,ttext,64);
            int estate=GetElementState(k);
            if ( estate & 4 )
            {
                if ( acount+1 >= 16 || y + MENU_TextHeight(ttext)+(active>0?MENU_TextSeparation():0) > limit.y1)
                {
                    topentry++;
                    checked=false;
                }
            }
            if ( estate & 1 )
            {
                acount++;
                y+=MENU_TextHeight(ttext)+(active>0?MENU_TextSeparation():0);
            }
        }
    }

    active=0;
    inuse.y1=inuse.y0+2*MENU_BorderSpaceFactor()+2*MENU_BorderSizeFactor();
    for ( int i=topentry; i<TotalEntries(); i++ )
    {
        state[active]=GetElementState(i);
        if ( state[active] & 1 )
        {
            GetElementText(i,text[active],64);
            if ( inuse.y1 + MENU_TextHeight(text[i])+(active>0?MENU_TextSeparation():0) > limit.y1 )
                break;
            if ( active+1 >= 16 )
                break;
            active++;
            inuse.y1+=MENU_TextHeight(text[i])+(active>0?MENU_TextSeparation():0);
        }
    }
}
